class Solution {
    public List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        Integer[] res = new Integer[n];
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int[] tree = new int[n + 1]; // 1-indexed Fenwick
        for (int i = n - 1; i >= 0; i--) {
            int rank = lowerBound(sorted, nums[i]) + 1; // 1..n
            res[i] = query(tree, rank - 1);
            update(tree, rank, n);
        }
        return Arrays.asList(res);
    }

    private int lowerBound(int[] a, int target) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    private void update(int[] tree, int i, int n) {
        for (; i <= n; i += i & (-i)) tree[i]++;
    }

    private int query(int[] tree, int i) {
        int s = 0;
        for (; i > 0; i -= i & (-i)) s += tree[i];
        return s;
    }
}

